from typing import List, Tuple

def merge_overlapping_intervals_with_weights(
    intervals: List[Tuple[float, float, float]]
) -> List[Tuple[float, float, float]]:
    if not isinstance(intervals, list):
        raise TypeError('Intervals must be a list')
    if not intervals:
        return []

    for it in intervals:
        if not (isinstance(it, (list, tuple)) and len(it) == 3):
            raise ValueError('Each interval must be a (start, end, weight) tuple')
        s, e, w = it
        if s >= e:
            raise ValueError(f'Start ({s}) must be strictly less than end ({e})')

    points = sorted(set([s for s, e, w in intervals] + [e for s, e, w in intervals]))

    segments = []
    for i in range(len(points) - 1):
        seg_start = points[i]
        seg_end = points[i + 1]
        w_sum = sum(w for s, e, w in intervals if s <= seg_start and e >= seg_end)
        w_sum = round(w_sum, 4)
        if abs(w_sum) > 1e-9:
            segments.append((round(seg_start, 4), round(seg_end, 4), w_sum))

    if not segments:
        return []

    merged = [segments[0]]
    for cur in segments[1:]:
        prev_s, prev_e, prev_w = merged[-1]
        cur_s, cur_e, cur_w = cur
        if abs(prev_e - cur_s) < 1e-9 and abs(prev_w - cur_w) < 1e-9:
            merged[-1] = (prev_s, cur_e, prev_w)
        else:
            merged.append(cur)

    return merged
